package lk.repairdesk.api.repository; import lk.repairdesk.api.domain.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface RepairRequestRepository extends JpaRepository<RepairRequest,Long> { @Query("select r from RepairRequest r where (:status is null or r.status=:status) and (:customerId is null or r.customer.id=:customerId) and (:q is null or lower(r.title) like lower(concat('%',:q,'%')) or lower(r.description) like lower(concat('%',:q,'%')))") Page<RepairRequest> search(@Param("status") RepairStatus status,@Param("customerId") Long customerId,@Param("q") String q,Pageable pageable); }